@push('styles')<style>.product-edit-page{max-width:1120px}.product-section{margin-bottom:16px;padding:22px}.section-title{display:flex;gap:12px;margin-bottom:20px}.section-title>b{width:32px;height:32px;display:grid;place-items:center;border-radius:11px;background:#eef2ff;color:#4f46e5}.section-title h2{margin:0;font-size:16px}.section-title p{margin:5px 0 0;color:#667085;font-size:11px}.form-group label i{color:#f04438;font-style:normal}.editor{border:1px solid #dfe3ea;border-radius:14px;overflow:hidden}.editor-toolbar{display:flex;gap:5px;flex-wrap:wrap;padding:8px;background:#f8fafc;border-bottom:1px solid #edf0f4}.editor-toolbar button{border:1px solid #e4e7ec;background:#fff;border-radius:8px;padding:7px 10px;cursor:pointer}.editor-content{min-height:230px;padding:14px;outline:0;line-height:2;font-size:12px}.current-files{display:grid;gap:8px;margin-bottom:13px}.current-file{display:flex;gap:10px;align-items:center;border:1px solid #eaecf0;border-radius:12px;padding:10px}.current-file b,.current-file small{display:block}.current-file b{font-size:11px}.current-file small{font-size:9px;color:#98a2b3;margin-top:3px;word-break:break-all}.file-type{width:38px;height:38px;display:grid;place-items:center;border-radius:10px;background:#f2f4f7;font-size:9px;font-weight:900}.file-dropzone{border:2px dashed #cfd5df;border-radius:18px;padding:30px;text-align:center;background:#fafbff;display:flex;flex-direction:column;align-items:center;gap:8px}.file-dropzone.drag{border-color:#6366f1;background:#f5f7ff}.drop-icon{width:48px;height:48px;display:grid;place-items:center;border-radius:14px;background:#eef2ff;color:#4f46e5;font-size:24px}.file-dropzone strong{font-size:13px}.file-dropzone span{font-size:10px;color:#667085}.uploaded-list{display:grid;gap:8px;margin-top:12px}.uploaded-item{display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;border:1px solid #eaecf0;border-radius:12px;padding:10px}.uploaded-item strong,.uploaded-item small{display:block}.uploaded-item strong{font-size:11px}.uploaded-item small{font-size:9px;color:#98a2b3}.remove-file{border:0;background:#fff1f3;color:#c01048;border-radius:8px;padding:7px}.image-policy{margin-top:12px;padding:12px;border:1px solid #dfe4ff;background:#f8f9ff;border-radius:12px}.image-policy b,.image-policy span{display:block}.image-policy b{font-size:10px}.image-policy span{font-size:9px;color:#667085;margin-top:4px}@media(max-width:650px){.product-section{padding:16px}.uploaded-item{grid-template-columns:auto 1fr auto}}</style>@endpush
@push('scripts')<script>(()=>{const form=document.getElementById('editProductForm'),editor=document.getElementById('editor'),description=document.getElementById('description'),input=document.getElementById('fileInput'),drop=document.getElementById('dropzone'),list=document.getElementById('uploadedList'),ids=document.getElementById('uploadIds'),csrf=@json(csrf_token()),uploadUrl=@json(route('admin.products.uploads.store')),deleteUrl=@json(url('/admin/products/uploads'));let uploaded=[];const fmt=n=>(n/1048576).toFixed(1)+' MB';const sync=()=>description.value=editor.innerHTML.replace(/<h1\b[^>]*>(.*?)<\/h1>/gi,'<h2>$1</h2>');const render=()=>{ids.innerHTML=uploaded.map(x=>`<input type="hidden" name="upload_ids[]" value="${x.id}">`).join('');list.innerHTML=uploaded.map(x=>`<div class="uploaded-item"><div class="file-type">${x.extension}</div><div><strong>${x.name}</strong><small>${fmt(x.size)} · فایل جدید</small></div><button type="button" class="remove-file" data-id="${x.id}">حذف</button></div>`).join('')};async function upload(file){const fd=new FormData();fd.append('file',file);const p=form.querySelector('[name="storage_provider_id"]').value;if(p)fd.append('storage_provider_id',p);const r=await fetch(uploadUrl,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:fd});const d=await r.json();if(!r.ok||!d.ok)throw Error(d.message||'آپلود ناموفق بود');uploaded.push(d.file);render()}async function handle(files){for(const f of files){try{if(!/\.(pdf|doc|docx)$/i.test(f.name)||f.size>209715200)throw Error('فقط PDF، DOC، DOCX و حداکثر ۲۰۰MB مجاز است.');await upload(f)}catch(e){alert(f.name+'\n'+e.message)}}}document.querySelectorAll('.editor-toolbar button').forEach(b=>b.onclick=()=>{editor.focus();document.execCommand(b.dataset.cmd,false,b.dataset.value||null);sync()});document.getElementById('chooseFiles').onclick=()=>input.click();input.onchange=()=>handle(input.files);['dragenter','dragover'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(e=>drop.addEventListener(e,x=>{x.preventDefault();drop.classList.remove('drag')}));drop.addEventListener('drop',e=>handle(e.dataTransfer.files));list.addEventListener('click',async e=>{const b=e.target.closest('.remove-file');if(!b)return;const id=Number(b.dataset.id);const r=await fetch(deleteUrl+'/'+id,{method:'DELETE',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'}});if(r.ok)uploaded=uploaded.filter(x=>x.id!==id);render()});form.onsubmit=()=>sync()})();</script>@endpush